// Curiona — banque locale, questions originales en français.
// Les indices correct se rapportent toujours à l'ordre original des propositions.
const q = (id, category, subtheme, difficulty, question, options, correct, explanation, extra = {}) => ({
  id: `nat-${id}`, category, subtheme, difficulty,
  type: options.length === 2 ? 'boolean' : 'qcm', question, options, correct, explanation, ...extra,
});

